import {buildRecheckResults,confirmRecheckItem,resolutionLabels,recheckMarkdown} from './recheck-supplement.js';
import {reviewService as mockService} from './review-service.js';
import {engineProvider,requestJson} from './engine-adapter.js';
import {loadRecords,saveRecord,clearRecords} from './storage.js';
const modes={mock:'模拟演示',stub:'引擎模拟（stub）',engine:'引擎评审'};
const service=()=> $('mode').value==='engine'?engineProvider:mockService;
const isReal=()=>current&&current.mode!=='mock';
const safeUrl=s=>{try{const u=new URL(s);return ['http:','https:'].includes(u.protocol)?esc(u.href):'#';}catch{return '#';}};
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='mingjian-reviews-v1';let records=[],current=null,image=null,recheckImage=null,focused=null,busy=false,timer;
try{records=await loadRecords();const old=JSON.parse(localStorage.getItem(key)||'[]');for(const r of Array.isArray(old)?old:[]){if(!records.some(x=>x.id===r.id)){await saveRecord(r);records.push(r);}}localStorage.removeItem(key);}catch{status('无法读取本机记录；本次仍可操作与导出。');}
function status(t){$('status').textContent=t;clearTimeout(timer);timer=setTimeout(()=>$('status').textContent='',5000);}
function persist(){if(current){records=records.filter(r=>r.id!==current.id);records.unshift(structuredClone(current));saveRecord(current).catch(()=>status('记录保存失败，请及时导出报告。'));}history();}
function history(){$('history').innerHTML=records.map(r=>`<button class="history-item" data-id="${esc(r.id)}">${esc(r.context.name)}<small>${modes[r.mode]||r.mode} · v${r.version}</small></button>`).join('')||'<p class="muted">暂无评审记录</p>';}
async function loadImage(file){if(!file)return null;if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('请选择 PNG、JPG 或 WebP 图片。');if(file.size>15*1024*1024)throw Error('图片超过 15 MB，请压缩后再试。');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('无法读取图片，请重新选择。'));reader.readAsDataURL(file);});await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{if(Math.min(img.naturalWidth,img.naturalHeight)<200)reject(Error('截图最短边至少 200 像素'));else if(img.naturalWidth*img.naturalHeight>50000000)reject(Error('截图总像素不能超过 5000 万'));else resolve();};img.onerror=()=>reject(Error('图片损坏或无法解码。'));img.src=data;});return data;}
function setPreview(src,name){image=src;$('preview').src=src;$('preview').hidden=false;$('uploadBox').hidden=true;$('fileName').textContent=name+' · 可点击下方重新选择';$('demo').textContent='重新选择截图';}
$('imageInput').onchange=async e=>{try{const src=await loadImage(e.target.files[0]);if(src)setPreview(src,e.target.files[0].name);}catch(e){status(e.message);}e.target.value='';};
const context=()=>Object.fromEntries(['name','type','audience','goal','intent'].map(k=>[k,$(k).value.trim()]));
const fill=c=>['name','type','audience','goal','intent'].forEach(k=>$(k).value=c[k]||'');
$('demo').onclick=()=>{if(image){$('imageInput').click();return;}setPreview('demo.svg','内置注册界面示例');fill({name:'注册页面 · 首次体验评审',type:'web',audience:'第一次使用的新用户',goal:'填写账号信息并完成注册',intent:'清楚说明输入要求，突出注册入口'});};
async function action(task){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);$('status').textContent='正在处理，请稍候（引擎请求最多等待 180 秒）…';try{await task();persist();render();status('已完成：'+(modes[current?.mode]||''));}catch(e){status('操作失败：'+e.message);}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);$('recheck').disabled=!recheckImage;}}
$('form').onsubmit=e=>{e.preventDefault();if(!image){status('请先上传截图或使用内置示例。');return;}const c=context();if(!c.name||!c.audience||!c.goal){status('请填写评审名称、目标用户和核心任务。');return;}action(async()=>{if(current&&current.mode==='mock'&&$('mode').value==='mock'){const next=structuredClone(current);next.context=c;current=await mockService.reviseReview(next,'设计目标已更新，模拟重新评审');}else current=await service().createReview({image,context:c},current);$('setup').hidden=true;});};
function render(){history();if(!current)return;$('setup').hidden=true;$('workspace').hidden=false;$('export').hidden=false;$('pageTitle').textContent=current.context.name;$('contextText').textContent=`${current.context.audience} · ${current.context.goal}`;$('version').textContent=`v${current.version} · ${modes[current.mode]}`;$('reviewImage').src=current.image;$('step1').classList.remove('selected');$('step2').classList.toggle('selected',!current.previousImage);$('step3').classList.toggle('selected',!!current.previousImage);const count=s=>current.issues.filter(i=>i.reviewStatus===s).length;$('stats').innerHTML=[['候选问题',current.issues.filter(i=>i.decision==='candidate_issue').length],['人工已确认',count('confirmed')],['待审核',count('pending')],['待验证',count('verify')]].map(([t,n])=>`<div class="stat"><strong>${n}</strong>${t}</div>`).join('');$('count').textContent=`/ ${current.issues.length}`;const order={critical:0,high:1,medium:2,low:3};const list=current.issues.filter(i=>($('filter').value==='all'||i.reviewStatus===$('filter').value)&&($('severityFilter').value==='all'||i.severity===$('severityFilter').value)).sort((a,b)=>order[a.severity]-order[b.severity]);$('issues').innerHTML=list.map((i)=>`<article class="panel issue ${focused===i.id?'focused':''}" data-id="${esc(i.id)}"><div class="issue-head"><h3>${esc(i.title)}</h3><span class="badge ${i.severity}">${({critical:'严重',high:'高',medium:'中',low:'低'})[i.severity]}</span></div><span class="badge">${i.decision==='insufficient_evidence'?'证据不足':'候选问题'}</span><dl>${[['原则',i.principle],['检测',i.detection],['描述',i.description],['建议',i.suggestion]].map(([a,b])=>`<dt>${a}</dt><dd>${esc(b)}</dd>`).join('')}</dl><div class="source">判据 ${esc(i.ruleId)} · ${esc(i.heuristic)}<br>${i.sources?i.sources.map(s=>`<a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)}</a> · ${esc(s.relationship)}`).join("<br>"):"小组操作化示例 · 非官方合规声明"}<br>证据：${esc(i.evidence?.description||(i.position?"预设示例位置，需人工核验":"暂无位置证据"))}${i.evidence?.visible_text?`<br>可见文字：${esc(i.evidence.visible_text)}`:""}${i.confidence!=null?`<br>模型置信度：${Math.round(i.confidence*100)}%（不是准确率）`:""}</div><div class="actions">${[['confirmed','确认问题'],['rejected','驳回'],['verify','待验证'],['pending','撤销审核']].map(([s,t])=>`<button data-state="${s}" class="${i.reviewStatus===s?'chosen':''}" aria-pressed="${i.reviewStatus===s}">${t}</button>`).join('')}</div><label>严重度<select data-severity aria-label="${esc(i.title)}的严重度">${[['critical','严重'],['high','高'],['medium','中'],['low','低']].map(([v,t])=>`<option value="${v}" ${i.severity===v?'selected':''}>${t}</option>`).join('')}</select></label><label>审核理由<textarea data-note placeholder="说明确认、驳回或等级调整的原因">${esc(i.note)}</textarea></label>${i.engineDisposition?`<p class="muted">${esc(i.engineDisposition)}</p>`:''}${i.recheckStatus?`<p class="recheck-status">${esc(i.recheckStatus)}（预设结果）</p>`:''}</article>`).join('')||'<div class="panel empty">当前筛选下没有问题</div>';$('markers').innerHTML=current.issues.filter(i=>i.position).map(i=>`<button class="marker ${i.position.width?'evidence-box':''} ${focused===i.id?'focused':''}" data-id="${esc(i.id)}" style="left:${i.position.x*100}%;top:${i.position.y*100}%;${i.position.width?`width:${i.position.width*100}%;height:${i.position.height*100}%;`:""}" aria-label="定位${esc(i.title)}">${current.issues.indexOf(i)+1}</button>`).join('');syncMode();const raw=current.rawReport;const labels={candidate_issue:'候选问题',no_visible_issue:'未见明显问题',insufficient_evidence:'证据不足',not_applicable:'不适用'};$('diagnostics').innerHTML=raw?`<p>引擎 ${esc(raw.model.provider)} / ${esc(raw.model.model)} · 判据 ${esc(raw.criteria_version)} · ${esc(raw.status==='partial'?'部分完成':'完成')}</p><p>${Object.entries(labels).map(([k,v])=>v+'：'+(raw.summary[k==='candidate_issue'?'candidate_issues':k]??0)).join(' / ')}</p>${(raw.warnings||[]).map(w=>`<p>警告：${esc(w)}</p>`).join('')}${(raw.screen_analysis?.uncertainties||[]).map(w=>`<p>不确定性：${esc(w)}</p>`).join('')}${raw.rule_results.map(x=>`<p>${esc(x.rule_id)} · ${esc(labels[x.decision])}：${esc(x.reason)}</p>`).join('')}${current.followup?`<h3>本轮发送的反馈上下文</h3><pre style="white-space:pre-wrap">${esc(current.followup.scenario)}</pre>`:''}${current.comparison?`<h3>上轮记录（${esc(current.comparison.id)}）</h3>${current.comparison.issues.map(i=>`<p>${esc(i.title)} · ${esc(i.reviewStatus)}</p>`).join('')}<p>两轮结果未自动匹配，问题是否解决需人工确认。</p><label>人工对照结论<textarea id="comparisonNote">${esc(current.comparisonNote||'')}</textarea></label>`:''}`:'模拟数据：不包含完整判据检测结果。';if($('comparisonNote'))$('comparisonNote').onchange=e=>{current.comparisonNote=e.target.value;persist();};renderRecheckResults();$('logs').innerHTML=current.logs.slice().reverse().map(l=>`<p>${esc(new Date(l.at).toLocaleString())}<br>${esc(l.text)}</p>`).join('');}
$('issues').onclick=e=>{const card=e.target.closest('[data-id]');if(!card)return;focused=card.dataset.id;const i=current.issues.find(i=>i.id===focused);const state=e.target.dataset.state;if(state){i.reviewStatus=state;persist();}if(e.target.tagName!=='TEXTAREA'&&e.target.tagName!=='SELECT')render();};
$('issues').oninput=e=>{if(!e.target.hasAttribute('data-note'))return;const id=e.target.closest('[data-id]').dataset.id;current.issues.find(i=>i.id===id).note=e.target.value;persist();};
$('issues').onchange=e=>{const card=e.target.closest('[data-id]');if(!card)return;const i=current.issues.find(i=>i.id===card.dataset.id);if(e.target.hasAttribute('data-severity')){i.originalSeverity??=i.severity;i.severity=e.target.value;}if(e.target.hasAttribute('data-note')){i.note=e.target.value;persist();return;}persist();render();};
$('markers').onclick=e=>{const m=e.target.closest('[data-id]');if(m){focused=m.dataset.id;$('filter').value='all';$('severityFilter').value='all';render();Array.from(document.querySelectorAll('article[data-id]')).find(el=>el.dataset.id===focused)?.scrollIntoView({behavior:'smooth',block:'center'});}};
$('filter').onchange=render;$('severityFilter').onchange=render;
$('revise').onclick=()=>{const feedback=$('feedback').value.trim();if(isReal()){current.logs.push({at:new Date().toISOString(),text:'提交前保存人工反馈：'+feedback,feedback:current.issues.map(({id,reviewStatus,severity,note})=>({id,reviewStatus,severity,note}))});persist();}action(async()=>{current=await (isReal()?engineProvider:mockService).reviseReview(current,feedback);$('feedback').value='';});};
$('editGoal').onclick=()=>{fill(current.context);image=current.image;setPreview(image,'当前截图');$('setup').hidden=false;$('workspace').hidden=true;$('step1').classList.add('selected');$('step2').classList.remove('selected');$('step3').classList.remove('selected');};
$('recheckInput').onchange=async e=>{try{const src=await loadImage(e.target.files[0]);if(src){recheckImage=src;$('recheckPreview').innerHTML=`<img alt="修改稿预览" src="${src}">`;$('recheck').disabled=false;}}catch(e){status(e.message);}e.target.value='';};
$('recheck').onclick=()=>action(async()=>{const previous=structuredClone(current);current=await (isReal()?engineProvider:mockService).recheckReview(current,recheckImage,$('feedback').value.trim());current.comparison=previous;current.recheckResults=buildRecheckResults(previous,current);recheckImage=null;$('recheckPreview').innerHTML='';});
function reset(){current=null;image=null;recheckImage=null;focused=null;$('form').reset();$('workspace').hidden=true;$('setup').hidden=false;$('export').hidden=true;$('recheckResults').hidden=true;$('preview').hidden=true;$('uploadBox').hidden=false;$('demo').textContent='没有截图？使用内置示例 →';$('fileName').textContent='建议上传文字清晰、包含主要操作区的完整界面。';$('pageTitle').textContent='让每一次设计判断，都有依据。';$('step1').classList.add('selected');$('step2').classList.remove('selected');$('step3').classList.remove('selected');$('recheckPreview').innerHTML='';$('recheck').disabled=true;$('feedback').value='';syncMode();}
$('new').onclick=reset;$('clear').onclick=()=>{if(confirm('清除当前浏览器中的全部评审记录？请先导出需要保留的报告。')){clearRecords().then(()=>{records=[];reset();history();status('本机记录已清除');}).catch(()=>status('清除失败，请重试'));}};
$('history').onclick=e=>{const b=e.target.closest('[data-id]');if(b){reset();current=structuredClone(records.find(r=>r.id===b.dataset.id));$('mode').value=current.mode==='mock'?'mock':'engine';render();}};
$('export').onclick=()=>{const r=current;const text=['# '+r.context.name,'',`> ${modes[r.mode]}：${r.mode==='engine'?'模型发现仍需人工审核':'结果为模拟，不代表真实图片分析'}`,'',`版本：v${r.version}`,`评审 ID：${r.id}`,`模型：${r.rawReport?.model?.provider||'mock'} / ${r.rawReport?.model?.model||'mock'}`,`判据版本：${r.rawReport?.criteria_version||'示例'}`,`完成状态：${r.rawReport?.status||'模拟完成'}`,`警告：${(r.rawReport?.warnings||[]).join('；')||'无'}`,`目标用户：${r.context.audience}`,`核心任务：${r.context.goal}`,`设计意图：${r.context.intent||'未填写'}`,'',...r.issues.flatMap(i=>[`## ${i.title}`,`- 严重度：${i.severity}${i.originalSeverity?'（原值：'+i.originalSeverity+'）':''}`,`- 检测结论：${i.decision}`,`- 人工审核：${i.reviewStatus}`,`- 判据：${i.ruleId} / Nielsen ${i.heuristic}，小组操作化，非官方合规声明`,`- 原则：${i.principle}`,`- 检测：${i.detection}`,`- 描述：${i.description}`,`- 建议：${i.suggestion}`,`- 审核理由：${i.note||'未填写'}`,`- 复审：${i.recheckStatus||'未复审'}`,`- 证据：${i.evidence?.description||'示例/无'}`,`- 来源：${(i.sources||[]).map(s=>s.name+' '+s.url+' '+s.relationship).join('；')||'模拟来源'}`,'']),'## 本轮提交上下文',r.followup?.scenario||'首次评审或目标更新',...recheckMarkdown(r.recheckResults),'## 版本对照',r.comparisonNote||'未填写人工对照结论',r.previousId?'上一轮：'+r.previousId:'无上一轮','## 判据检查',...(r.ruleResults||[]).map(x=>`${x.rule_id} ${x.decision}：${x.reason}`),'## 操作记录',...r.logs.map(l=>`${l.at} ${l.text}`)].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`评审报告-v${r.version}.md`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('报告已导出');};history();

function syncMode(){const mode=current?.mode||$('mode').value;document.querySelector('.mode').textContent=modes[mode];document.querySelector('.notice').textContent=mode==='mock'?'模拟演示：问题、位置和复审状态均为预设示例。':mode==='stub'?'引擎返回 stub 模拟结果，不代表真实图片分析。':'引擎模式：截图传给本地后端，并可能发送至其配置的模型；所有发现需人工审核。';$('form').querySelector('button[type=submit]').textContent=$('mode').value==='engine'?'开始引擎评审 →':'开始模拟评审 →';document.querySelector('.feedback .muted').textContent=isReal()?'C 将原问题摘要与反馈填入场景字段，再调用同一引擎；上限 2000 字。':'预设规则只更新示例结论，不会训练模型或分析图片。';$('revise').textContent=isReal()?'提交反馈并再次调用引擎':'提交反馈并模拟重评';$('editGoal').textContent='修改目标并重新评审';$('recheck').textContent=isReal()?'评审修改稿（不自动判断解决）':'开始模拟复审';$('recheckArea').querySelector('p').textContent=isReal()?'将新版截图、原问题摘要与人工反馈送入同一引擎；不传原图，解决状态由人确认。':'基于原问题生成预设模拟复审状态。';document.querySelector('.image-stage').nextElementSibling.textContent=isReal()?'证据框由引擎提供，点击问题可定位；仍需人工核验。':'编号为示例位置，不是图片识别结果。';}
$('mode').onchange=()=>{if(current){status('模式用于下一次新评审；当前记录保持原数据来源。');}syncMode();};
$('health').onclick=async()=>{try{const h=await requestJson('/healthz');const c=await requestJson('/api/criteria');$('healthState').textContent=`${h.status} · 判据 ${c.version} / ${c.rule_count} 条 · 已配置模型：${(h.configured_providers||[]).join('、')||'无'} · stub ${h.stub_allowed?'允许':'禁用'}`;}catch(e){$('healthState').textContent=e.message;}};
syncMode();

function renderRecheckResults(){
 if(current?.comparison&&!current.recheckResults){current.recheckResults=buildRecheckResults(current.comparison,current);persist();}
 const box=$('recheckResults');const result=current?.recheckResults;box.hidden=!result;if(!result)return;
 box.innerHTML=`<h2>逐问题复审结果</h2><p class="muted">C 补充层 · ${result.is_stub?'含模拟数据，结论只供流程演示':'人工核验'}。候选关联不代表同一问题；请对照新版截图确认每条旧问题。后续由 B 原生复审替换。</p>${result.items.map((i,index)=>`<form data-recheck-index="${index}" class="recheck-item"><h3>${index+1}. ${esc(i.title)}</h3><p class="muted">原问题：${esc(i.previous_description||'')}<br>上轮审核：${esc(i.previous_review_status)} · 备注：${esc(i.previous_note)}<br>当前：${esc(resolutionLabels[i.resolution])} · ${i.human_confirmation==='confirmed'?'人工已确认':'待人工确认'}</p><label>复审结论<select name="resolution">${Object.entries(resolutionLabels).map(([v,t])=>`<option value="${v}" ${i.resolution===v?'selected':''}>${t}</option>`).join('')}</select></label><label>关联新版发现（可选）<select name="currentId"><option value="">不关联</option>${current.issues.map(n=>`<option value="${esc(n.id)}" ${i.current_finding_ids.includes(n.id)?'selected':''}>${esc(n.title)}${i.candidate_current_finding_ids.includes(n.id)?'（同判据候选）':''}</option>`).join('')}</select></label><label>判断理由<textarea name="reason" required maxlength="1500">${esc(i.reason)}</textarea></label><label>新版证据位置或观察现象<textarea name="evidence" maxlength="1500" placeholder="例如：新版右下角保存按钮已改为蓝色，文字完整可读">${esc(i.current_evidence_description)}</textarea></label><button class="secondary" type="submit">保存并确认此条复审结果</button></form>`).join('')}`;
}
$('recheckResults').onsubmit=e=>{e.preventDefault();const form=e.target.closest('[data-recheck-index]');if(!form)return;const index=Number(form.dataset.recheckIndex);const data=new FormData(form);try{current.recheckResults.items[index]=confirmRecheckItem(current.recheckResults.items[index],{resolution:data.get('resolution'),reason:data.get('reason'),evidence:data.get('evidence'),currentIds:data.get('currentId')?[data.get('currentId')]:[]},current);current.logs.push({at:new Date().toISOString(),text:'人工确认复审：'+current.recheckResults.items[index].title+' / '+resolutionLabels[data.get('resolution')]});persist();renderRecheckResults();status('逐问题复审结果已保存，导出会包含该结论');}catch(err){status(err.message);}};
